<?php require '_header.php';$page_title='Trip requests';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$note=trim($_POST['admin_note']??'');if(in_array($status,['pending','approved','rejected'],true)){$q=$pdo->prepare('UPDATE bookings SET status=?,admin_note=? WHERE id=?');$q->execute([$status,$note?:null,$id]);flash('Request status updated. The user can now see this update in My Trips.');redirect('bookings.php');}}$rows=$pdo->query('SELECT b.*,u.name user_name,u.email,d.name destination,d.price FROM bookings b JOIN users u ON u.id=b.user_id JOIN destinations d ON d.id=b.destination_id ORDER BY b.created_at DESC')->fetchAll();?><div class="admin-top"><div><span class="eyebrow">BOOKING WORKFLOW</span><h1>Trip requests</h1><p class="muted">Approving a request unlocks the payment page for the user.</p></div></div><?php if(!$rows):?><div class="empty">No requests have been submitted yet.</div><?php else:?><div class="table-wrap"><table><tr><th>Request / customer</th><th>Trip details</th><th>Status</th><th>Review action</th></tr><?php foreach($rows as $r):?><tr><td><b>#<?=$r['id']?> · <?=e($r['user_name'])?></b><br><?=e($r['email'])?><br><small><?=e($r['created_at'])?></small></td><td><?=e($r['destination'])?><br><?=e($r['travel_date'])?> · <?= (int)$r['travelers']?> traveller(s)<br>₹<?=number_format((float)$r['price']*(int)$r['travelers'])?><br><small><?=e($r['message'])?></small></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span><?php if($r['admin_note']):?><br><small><?=e($r['admin_note'])?></small><?php endif;?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="pending" <?=$r['status']==='pending'?'selected':''?>>Pending</option><option value="approved" <?=$r['status']==='approved'?'selected':''?>>Approve</option><option value="rejected" <?=$r['status']==='rejected'?'selected':''?>>Reject</option></select><input name="admin_note" maxlength="500" placeholder="Message to user" value="<?=e($r['admin_note'])?>"><button class="small-btn">Save</button></form></td></tr><?php endforeach;?></table></div><?php endif;?><?php require '_footer.php';?>
